package oops;

public class Rectangle {
	double length;
	double breadth;
	

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Rectangle rect1=new Rectangle();
		rect1.length=20;
		rect1.breadth=30;
		
		Rectangle rect2 = new Rectangle();
		rect2.length=10;
		rect2.breadth=20;
		System.out.println(rect1);
		System.out.println(rect2);
		

	}

}
